//! `cargo xtask gen-sdks [--check] [--target NAME]`: every language SDK, generated from one description.
//!
//! The sources of truth are the schema catalog and the two ABI crates; [`model::SdkSpec`] is what they add up to, and a
//! [`Target`] turns a spec into files. The command writes them (or, with `--check`, compares them with the tree and fails
//! on any difference, like `abi-check`). Every generated file starts with a banner that names the generator, the target and
//! the catalog hash, so a reader who opens one knows not to edit it and which command rewrites it.
//!
//! Adding a language is one [`Target`] implementation and one line in [`targets`]; `docs/sdk-generator.md` is the contract.
//!
//! The targets, and what they own:
//!
//! | target       | writes                                                                                   |
//! | ------------ | ---------------------------------------------------------------------------------------- |
//! | `rust`       | `crates/gnoblin-core/src/generated/`: schema names, typed node classes, the error kinds   |
//! | `python`     | `data/python/gnoblin/_generated/`: typed node classes and `.pyi`, ABI constants          |
//! | `typescript` | `data/js/gnoblin-core/generated/`: node-class types and the schema table, ABI constants  |

mod model;
mod python;
mod rust;
mod text;
mod typescript;

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

pub use model::SdkSpec;

/// The command that regenerates everything, named in every banner and error.
pub const COMMAND: &str = "cargo xtask gen-sdks";

/// The comment syntax of a generated file's banner.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Comment {
    /// `// text`: Rust, TypeScript, C.
    Slashes,
    /// `# text`: Python, TOML, shell.
    Hash,
}

/// One generated file.
pub struct File {
    /// The path relative to the workspace root.
    pub path: String,
    /// The comment syntax of the banner this file gets; `None` for a file that must not start with one.
    pub comment: Option<Comment>,
    /// The content, without the banner.
    pub text: String,
}

/// A language an SDK is generated for.
pub trait Target {
    /// The name `--target` takes and the banner prints.
    fn name(&self) -> &'static str;

    /// The directories (relative to the workspace root) this target owns completely: every file in them is generated, so
    /// `--check` fails on a file that is there and is not produced any more.
    fn owned_dirs(&self) -> &'static [&'static str];

    /// Renders the target's files.
    fn generate(&self, spec: &SdkSpec) -> Result<Vec<File>, String>;
}

/// Every target, in the order they run.
pub fn targets() -> Vec<Box<dyn Target>> {
    vec![
        Box::new(rust::RustTarget),
        Box::new(python::PythonTarget),
        Box::new(typescript::TypeScriptTarget),
    ]
}

/// The banner of a generated file.
fn banner(spec: &SdkSpec, target: &str, comment: Comment) -> String {
    let lines = [
        format!("GENERATED by `{COMMAND}` (target: {target}). Do not edit: change the schema or the ABI crates,"),
        "then run the command again; `--check` fails the build while a generated file is stale.".to_owned(),
        format!(
            "catalog 0x{:016x}, {}",
            spec.catalog_hash,
            spec.libraries
                .iter()
                .map(|library| format!("{}-abi {}.{}", library.name, library.abi.0, library.abi.1))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    ];
    let prefix = match comment {
        Comment::Slashes => "//",
        Comment::Hash => "#",
    };
    let mut text = String::new();
    for line in lines {
        text.push_str(prefix);
        text.push(' ');
        text.push_str(&line);
        text.push('\n');
    }
    text
}

/// Formats Rust source the way `cargo fmt` would, with the toolchain the repository pins and its `rustfmt.toml`, so a
/// generated Rust file passes the same format check as a hand-written one and a diff of it reads like one.
fn format_rust(source: &str, config: &Path) -> Result<String, String> {
    use std::io::Write as _;
    use std::process::{Command, Stdio};
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--config-path"])
        .arg(config)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| format!("cannot run rustfmt (it is a component of the pinned toolchain): {error}"))?;
    let mut stdin = child.stdin.take().ok_or("rustfmt has no stdin")?;
    let input = source.to_owned();
    let writer = std::thread::spawn(move || stdin.write_all(input.as_bytes()));
    let output = child
        .wait_with_output()
        .map_err(|error| format!("rustfmt did not finish: {error}"))?;
    writer
        .join()
        .map_err(|_| "the rustfmt writer panicked".to_owned())?
        .map_err(|error| format!("cannot feed rustfmt: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt refused the generated source: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    String::from_utf8(output.stdout).map_err(|error| format!("rustfmt wrote invalid UTF-8: {error}"))
}

/// A target with the files it rendered: `(path, full text)` pairs, banners included.
pub type Rendered = (Box<dyn Target>, Vec<(String, String)>);

/// Renders every selected target to `(path, full text)` pairs, banners included.
pub fn render(spec: &SdkSpec, only: Option<&str>) -> Result<Vec<Rendered>, String> {
    let mut rendered = Vec::new();
    for target in targets() {
        if only.is_some_and(|only| only != target.name()) {
            continue;
        }
        let mut files = Vec::new();
        for file in target.generate(spec)? {
            let mut text = match file.comment {
                Some(comment) => format!("{}\n{}", banner(spec, target.name(), comment), file.text),
                None => file.text,
            };
            if file.path.ends_with(".rs") {
                text = format_rust(&text, &spec.root.join("rustfmt.toml"))
                    .map_err(|error| format!("{}: {error}", file.path))?;
            }
            files.push((file.path, text));
        }
        let mut seen = BTreeSet::new();
        for (path, _) in &files {
            if !seen.insert(path.clone()) {
                return Err(format!("target {} generates {path} twice", target.name()));
            }
        }
        rendered.push((target, files));
    }
    if rendered.is_empty() {
        return Err(format!("no target named {}", only.unwrap_or("")));
    }
    Ok(rendered)
}

/// What differs between the rendered files and the tree under `root`.
pub struct Drift {
    /// Files whose content differs, or that do not exist yet.
    pub changed: Vec<String>,
    /// Files in an owned directory that no target produces.
    pub stale: Vec<String>,
}

impl Drift {
    /// True when the tree matches.
    pub fn is_clean(&self) -> bool {
        self.changed.is_empty() && self.stale.is_empty()
    }
}

fn files_under(root: &Path, dir: &str) -> Vec<String> {
    fn walk(base: &Path, dir: &Path, out: &mut Vec<String>) {
        let Ok(entries) = fs::read_dir(dir) else { return };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(base, &path, out);
            } else if let Ok(relative) = path.strip_prefix(base) {
                out.push(relative.to_string_lossy().into_owned());
            }
        }
    }
    let mut out = Vec::new();
    walk(root, &root.join(dir), &mut out);
    out.sort();
    out
}

/// Compares the rendered files with the tree.
pub fn drift(root: &Path, rendered: &[Rendered]) -> Drift {
    let mut changed = Vec::new();
    let mut stale = Vec::new();
    for (target, files) in rendered {
        for (path, text) in files {
            if fs::read_to_string(root.join(path)).ok().as_deref() != Some(text.as_str()) {
                changed.push(path.clone());
            }
        }
        let expected: BTreeSet<&str> = files.iter().map(|(path, _)| path.as_str()).collect();
        for dir in target.owned_dirs() {
            for path in files_under(root, dir) {
                if !expected.contains(path.as_str()) {
                    stale.push(path);
                }
            }
        }
    }
    Drift { changed, stale }
}

/// Writes the rendered files, removing stale ones from the owned directories. Returns the paths written.
pub fn write(root: &Path, rendered: &[Rendered]) -> Result<Vec<String>, String> {
    let report = drift(root, rendered);
    for path in &report.stale {
        fs::remove_file(root.join(path)).map_err(|error| format!("cannot remove {path}: {error}"))?;
    }
    let mut written = Vec::new();
    for (_, files) in rendered {
        for (path, text) in files {
            if !report.changed.contains(path) {
                continue;
            }
            let full: PathBuf = root.join(path);
            if let Some(parent) = full.parent() {
                fs::create_dir_all(parent).map_err(|error| format!("cannot create {}: {error}", parent.display()))?;
            }
            fs::write(&full, text).map_err(|error| format!("cannot write {path}: {error}"))?;
            written.push(path.clone());
        }
    }
    Ok(written)
}

const USAGE: &str = "usage: cargo xtask gen-sdks [--check] [--target rust|python|typescript]";

/// The `gen-sdks` subcommand.
pub fn run(args: &[String]) -> ExitCode {
    let mut check = false;
    let mut only: Option<String> = None;
    let mut index = 0;
    while index < args.len() {
        match args[index].as_str() {
            "--check" => check = true,
            "--target" => {
                index += 1;
                match args.get(index) {
                    Some(name) => only = Some(name.clone()),
                    None => {
                        eprintln!("[gen-sdks] --target needs a name\n{USAGE}");
                        return ExitCode::from(2);
                    }
                }
            }
            other => {
                eprintln!("[gen-sdks] unexpected argument `{other}`\n{USAGE}");
                return ExitCode::from(2);
            }
        }
        index += 1;
    }
    let root = Path::new(".");
    let result = SdkSpec::load(root).and_then(|spec| render(&spec, only.as_deref()));
    let rendered = match result {
        Ok(rendered) => rendered,
        Err(error) => {
            eprintln!("[gen-sdks] {error}");
            return ExitCode::from(2);
        }
    };
    if check {
        let report = drift(root, &rendered);
        if report.is_clean() {
            let count: usize = rendered.iter().map(|(_, files)| files.len()).sum();
            println!("[gen-sdks] {count} generated files are fresh");
            return ExitCode::SUCCESS;
        }
        for path in &report.changed {
            println!("[gen-sdks] stale: {path}");
        }
        for path in &report.stale {
            println!("[gen-sdks] no longer generated: {path}");
        }
        eprintln!(
            "[gen-sdks] the generated SDKs are out of date with the schema or the ABI crates; run `{COMMAND}` and commit"
        );
        return ExitCode::FAILURE;
    }
    match write(root, &rendered) {
        Ok(written) => {
            for path in &written {
                println!("[gen-sdks] wrote {path}");
            }
            println!("[gen-sdks] {} files written", written.len());
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("[gen-sdks] {error}");
            ExitCode::from(2)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn root() -> &'static Path {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("xtask lives in the workspace")
    }

    /// The committed SDKs are what the generator writes now. `cargo xtask gen-sdks --check` is the same test as a command; this
    /// one makes `cargo test` fail on drift as well.
    #[test]
    fn the_committed_sdks_are_fresh() {
        let spec = SdkSpec::load(root()).expect("the specification loads");
        let rendered = render(&spec, None).expect("every target renders");
        let report = drift(root(), &rendered);
        assert!(
            report.is_clean(),
            "stale: {:?}; no longer generated: {:?}; run `{COMMAND}`",
            report.changed,
            report.stale
        );
    }

    #[test]
    fn every_generated_file_carries_the_banner_and_the_catalog_hash() {
        let spec = SdkSpec::load(root()).expect("the specification loads");
        let hash = format!("0x{:016x}", spec.catalog_hash);
        for (target, files) in render(&spec, None).expect("every target renders") {
            assert!(!files.is_empty(), "{} renders nothing", target.name());
            for (path, text) in files {
                let head: String = text.lines().take(6).collect::<Vec<_>>().join("\n");
                assert!(
                    head.contains("GENERATED by `cargo xtask gen-sdks`"),
                    "{path} has no banner"
                );
                assert!(head.contains(&hash), "{path} does not name the catalog hash");
            }
        }
    }

    #[test]
    fn targets_have_distinct_names_and_disjoint_owned_directories() {
        let all = targets();
        let mut names = BTreeSet::new();
        let mut dirs = BTreeSet::new();
        for target in &all {
            assert!(names.insert(target.name()), "{} twice", target.name());
            for dir in target.owned_dirs() {
                assert!(dirs.insert(*dir), "{dir} is owned twice");
            }
        }
    }
}
